async read(file, signal, coalesceRanges = false) {
    signal.throwIfAborted();
    const archiveSize = this._archiveContent instanceof Blob ? this._archiveContent.size : this._archiveContent.byteLength;
    const offset = /** @type {unknown} */ (Reflect.get(file, 'offset'));
    const compressedSize = /** @type {unknown} */ (Reflect.get(file, 'compressedSize'));
    const compressionMethod = /** @type {unknown} */ (Reflect.get(file, 'compressionMethod'));
    if (
        typeof offset !== 'number' || !Number.isSafeInteger(offset) || offset < 0 ||
        typeof compressedSize !== 'number' || !Number.isSafeInteger(compressedSize) || compressedSize < 0 ||
        compressedSize > RAW_ZIP_WHOLE_ARCHIVE_MAX_BYTES ||
        (compressionMethod !== 0 && compressionMethod !== 8) ||
        offset > archiveSize - ZIP_LOCAL_FILE_HEADER_LENGTH
    ) {
        throw new DictionarySourceIntegrityError(`Raw ZIP metadata is invalid for '${file.filename}'`);
    }
    // Keep the existing small-archive path. Large Files/Blobs read only
    // validated entry ranges; an already-owned ArrayBuffer needs no copy.
    const ranged = this._archiveContent instanceof Blob && archiveSize > RAW_ZIP_WHOLE_ARCHIVE_MAX_BYTES;
    const rawFilename = /** @type {unknown} */ (Reflect.get(file, 'rawFilename'));
    const expectedFilenameLength = rawFilename instanceof Uint8Array && rawFilename.byteLength <= 0xffff ? rawFilename.byteLength : 0;
    // Include a bounded payload in the header read for entries without a
    // local extra field. A larger payload or extra field uses the exact read.
    const prefetchedPayloadLength = ranged && expectedFilenameLength > 0 && compressedSize <= RAW_ZIP_BATCH_MAX_PAYLOAD_BYTES ? compressedSize : 0;
    const readLength = Math.min(archiveSize - offset, ZIP_LOCAL_FILE_HEADER_LENGTH + expectedFilenameLength + prefetchedPayloadLength);
    const archiveBytes = ranged ?
        (coalesceRanges ? (await this._readCoalescedBlobRange(offset, readLength, signal)).bytes : await this._readBlobRange(offset, readLength, signal)) :
        await this._getArchiveBytes();
    signal.throwIfAborted();
    const headerOffset = ranged ? 0 : offset;
    const view = new DataView(archiveBytes.buffer, archiveBytes.byteOffset, archiveBytes.byteLength);
    if (view.getUint32(headerOffset, true) !== ZIP_LOCAL_FILE_HEADER_SIGNATURE) {
        throw new DictionarySourceIntegrityError(`Raw ZIP local header is invalid for '${file.filename}'`);
    }
    const localFlags = view.getUint16(headerOffset + 6, true);
    const localCompressionMethod = view.getUint16(headerOffset + 8, true);
    if ((localFlags & 0x1) !== 0 || localCompressionMethod !== compressionMethod) {
        throw new DictionarySourceIntegrityError(`Raw ZIP local header disagrees with central metadata for '${file.filename}'`);
    }
    const filenameLength = view.getUint16(headerOffset + 26, true);
    const extraFieldLength = view.getUint16(headerOffset + 28, true);
    const dataOffset = offset + ZIP_LOCAL_FILE_HEADER_LENGTH + filenameLength + extraFieldLength;
    if (!Number.isSafeInteger(dataOffset) || dataOffset > archiveSize || compressedSize > archiveSize - dataOffset) {
        throw new DictionarySourceIntegrityError(`Raw ZIP payload is out of bounds for '${file.filename}'`);
    }
    if (rawFilename instanceof Uint8Array) {
        if (filenameLength !== rawFilename.byteLength) {
            throw new DictionarySourceIntegrityError(`Raw ZIP local filename disagrees with central metadata for '${file.filename}'`);
        }
        const localFilenameOffset = headerOffset + ZIP_LOCAL_FILE_HEADER_LENGTH;
        for (let i = 0; i < filenameLength; ++i) {
            if (archiveBytes[localFilenameOffset + i] !== rawFilename[i]) {
                throw new DictionarySourceIntegrityError(`Raw ZIP local filename disagrees with central metadata for '${file.filename}'`);
            }
        }
    }
    if (ranged) {
        const relativeDataOffset = dataOffset - offset;
        if (relativeDataOffset <= archiveBytes.byteLength - compressedSize) {
            return archiveBytes.slice(relativeDataOffset, relativeDataOffset + compressedSize);
        }
        // An exact payload read can share a range with a different parser
        // group. Retain independently transferable ownership for each bank.
        if (coalesceRanges) {
            const {bytes, shared} = await this._readCoalescedBlobRange(dataOffset, compressedSize, signal);
            return shared ? Uint8Array.from(bytes) : bytes;
        }
        return await this._readBlobRange(dataOffset, compressedSize, signal);
    }
    return Uint8Array.from(archiveBytes.subarray(dataOffset, dataOffset + compressedSize));
}

